use super::*;
#[path="../feature-native-multiseed-factor/lib.rs"]mod frozen_source;
#[path="../feature-native-batch-reciprocals/lib.rs"]mod frozen_recovery;
fn add(p:u64,a:u64,x:Option<[u64;2]>,y:Option<[u64;2]>)->Option<[u64;2]>{let(Some([x1,y1]),Some([x2,y2]))=(x,y)else{return x.or(y)};if x1==x2&&(y1+y2)%p==0{return None;}let(n,d)=if x1==x2{((3*mul(x1,x1,p)+a)%p,2*y1%p)}else{((y2+p-y1)%p,(x2+p-x1)%p)};let m=mul(n,pow(d,p-2,p),p);let xx=(mul(m,m,p)+2*p-x1-x2)%p;Some([xx,(mul(m,(x1+p-xx)%p,p)+p-y1)%p])}
fn point(p:u64,a:u64,base:[u64;2],mut k:u64)->Option<[u64;2]>{let(mut out,mut cur)=(None,Some(base));while k>0{if k&1!=0{out=add(p,a,out,cur);}cur=add(p,a,cur,cur);k>>=1;}out}
#[test]fn split_windows_match_frozen_and_skip_only_residual(){
 let(mut splits,mut advances,mut skips,mut direct)=(0,0,0,0);
 for(p,a,b,r,base)in[(5,2,1,7,[0,1]),(7,0,3,13,[1,2]),(509,2,10,479,[3,68])]{let s=source::Source::new(p,a,b,r,base,128,32).unwrap();let ready=s.prepare().unwrap();let old=frozen_source::Source::new(p,a,b,r,base,128,32).unwrap();let oldready=old.prepare().unwrap();
  let mut starts=vec![0,1,2,3,r-3,r-2,r-1];if r==479{starts.extend([25,173,292,440]);}starts.sort_unstable();starts.dedup();
  for start in starts{let q=point(p,a,base,start);let full=oldready.window(q,17).unwrap();for length in [1,2,3,7]{let(initial,c)=ready.begin(q,length,17-length).unwrap();assert_eq!(initial.signs,full.signs[..length]);assert_eq!(initial.points,full.points[..length]);let mut cursor=Some(c);
   for i in length..17{let skip=i%3==0;let before=source::calls();let c=cursor.take().unwrap();let(e,next)=if skip{c.skip_sign()}else{c.advance()}.unwrap();let after=source::calls();assert_eq!(e.point,full.points[i]);assert_eq!(e.pairs.len(),1);assert_eq!(after.1-before.1,usize::from(e.method=="direct"));assert_eq!(after.2-before.2,usize::from(e.method=="direct"));direct+=usize::from(e.method=="direct");assert_eq!(after.0-before.0,usize::from(!skip&&e.point.is_some()));if skip{assert_eq!(e.sign,None);assert_eq!(e.ratio,None);skips+=1;}else{assert_eq!(e.sign,Some(full.signs[i]));let ratio=e.ratio.unwrap();assert_eq!(mul(ratio[0],full.ratios[i][1],p),mul(ratio[1],full.ratios[i][0],p));}assert_eq!(e.lane_updates,if r==7{3}else if r==13{5}else{23});assert_eq!(e.converted_points,if e.point.is_some(){e.lane_updates+1}else{0});assert_eq!(e.conversion_batches,usize::from(e.point.is_some()));cursor=Some(next);advances+=1;}
   assert!(matches!(cursor.unwrap().advance(),Err(source::Error::Limit)));splits+=1;
  }}
 }
 assert_eq!(splits,100);assert_eq!(advances,1375);println!("split_windows={splits} cursor_advances={advances} skipped_residuals={skips} direct_initializations_in_extensions={direct}");
}
#[test]fn frozen_decoder_recoveries_and_forward_checks(){
 let p=Program::construct(479,14,2,479,2500).unwrap();let s=Source::new(509,2,10,479,[3,68],128,16).unwrap();let ready=s.prepare().unwrap();let oldp=frozen_recovery::Program::construct(479,14,2,479,2500).unwrap();let olds=frozen_recovery::Source::new(509,2,10,479,[3,68]).unwrap();let oldready=olds.prepare().unwrap();
 let mut xs=vec![0,1,2,478];for line in include_str!("../feature-native-quartic-collapse/fibers.tsv").lines(){xs.extend(line.split('\t').map(|s|s.parse::<u64>().unwrap()));}xs.sort_unstable();xs.dedup();assert_eq!(xs.len(),20);
 let(mut extras,mut skips,mut steps,mut conversions,mut direct)=(0,0,0,0,0);let mut rows=String::from("scalar\tx\ty\trecovered\tsign_values\textra_offset\tsteps\tskipped_signs\textra_conversions\tinitial_conversions\tinitial_direct\textra_direct\n");
 for x in xs{let q=point(509,2,[3,68],x);let before=source::calls();let out=ready.recover(&p,q).unwrap();let after=source::calls();let old=oldready.recover(&oldp,q).unwrap();assert_eq!(out.value,old.value);assert_eq!(point(509,2,[3,68],out.value),q);assert_eq!((out.sign_values,out.extra_offset,out.steps,out.skipped_signs,out.conversions),(old.sign_values,old.extra_offset,old.steps,old.skipped_signs,old.conversions));assert_eq!(out.direct_phases,0);let expected=out.initial_direct_initializations+out.direct_phases;assert_eq!(after.1-before.1,expected);assert_eq!(after.2-before.2,expected);assert_eq!(after.0-before.0,out.sign_values-usize::from((0..14).any(|a|(x+a)%479==0)));assert!(expected<=2);direct+=expected;extras+=usize::from(out.extra_offset.is_some());skips+=out.skipped_signs;steps+=out.steps;conversions+=out.conversions;
 let(a,b)=q.map(|[a,b]|(a as i64,b as i64)).unwrap_or((-1,-1));rows.push_str(&format!("{x}\t{a}\t{b}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",out.value,out.sign_values,out.extra_offset.map(|e|e as i64).unwrap_or(-1),out.steps,out.skipped_signs,out.conversions,out.initial_conversions,out.initial_direct_initializations,out.direct_phases));
 }assert_eq!((extras,skips,steps,conversions),(16,4,20,480));println!("public_point_recoveries=20 forward_checks=20 extra_signs={extras} skipped_signs={skips} extra_steps={steps} extra_conversions={conversions} all_direct_initializations={direct}");if let Ok(dir)=std::env::var("TRANSPORT_RECOVERY_OUT"){std::fs::write(format!("{dir}/recovery.tsv"),rows).unwrap();}
}
#[test]fn limits_and_identity_cursor(){let s=source::Source::new(509,2,10,479,[3,68],128,16).unwrap();let ready=s.prepare().unwrap();assert!(ready.begin(None,0,1).is_err());assert!(matches!(ready.begin(None,14,3),Err(source::Error::Limit)));assert!(matches!(ready.begin(None,1,usize::MAX),Err(source::Error::Limit)));let(_,cursor)=ready.begin(None,1,0).unwrap();assert!(matches!(cursor.advance(),Err(source::Error::Limit)));assert!(ready.begin(Some([0,0]),2,1).is_err());
 let(_,cursor)=ready.begin(point(509,2,[3,68],478),1,3).unwrap();let(e,cursor)=cursor.skip_sign().unwrap();assert_eq!(e.point,None);assert_eq!(e.sign,None);let(e,cursor)=cursor.advance().unwrap();assert_eq!(e.sign,Some(1));assert_eq!(e.method,"anchor");let(e,_)=cursor.advance().unwrap();assert_eq!(e.sign,Some(chi(2,479)));assert_eq!(e.method,"anchor");
 let p=Program::construct(479,14,2,479,2500).unwrap();let s=Source::new(509,2,10,479,[3,68],128,15).unwrap();assert!(s.prepare().unwrap().recover(&p,None).is_err());assert!(Source::new(509,2,10,479,[3,68],1,16).is_err());
}
